function spacingScale(base, ratio, steps){
  base=(+base); if(isNaN(base)||base<=0)base=4;
  ratio=(+ratio); if(isNaN(ratio)||ratio<=0)ratio=1.5;
  steps=(+steps); if(isNaN(steps)||steps<1)steps=8; steps=Math.min(24,Math.round(steps));
  var out=[]; for(var i=0;i<steps;i++){ out.push(Math.round(base*Math.pow(ratio,i)*100)/100); }
  var css=out.map(function(v,i){return '--space-'+(i+1)+': '+v+'px;';}).join('\n');
  return {values:out, css:css, base:base, ratio:ratio, steps:steps};
}
var EXPORTS={spacingScale:spacingScale};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SpacingScaleForgePure = EXPORTS; }
